import type { FormEvent, RefObject } from "react";

type SearchFormProps = {
  username: string;
  validationMessage: string;
  canSearch: boolean;
  isPending: boolean;
  searchInputRef: RefObject<HTMLInputElement | null>;
  onSubmit: (event: FormEvent) => void;
  onUsernameChange: (value: string) => void;
};

export default function SearchForm({
  username,
  validationMessage,
  canSearch,
  isPending,
  searchInputRef,
  onSubmit,
  onUsernameChange,
}: SearchFormProps) {
  const usernameDescriptionIds = validationMessage
    ? "username-hint username-validation"
    : "username-hint";

  return (
    <form
      onSubmit={onSubmit}
      role="search"
      aria-label="GitHub commit search"
      aria-busy={isPending}
      className="w-full max-w-md flex flex-col gap-2 sm:flex-row"
    >
      <div className="relative flex-1">
        <label htmlFor="commit-search" className="sr-only">
          GitHub username
