          </div>
          <input
            ref={searchInputRef}
            id="commit-search"
            name="commit-search"
            type="search"
            value={username}
            onInput={(event) => onUsernameChange(event.currentTarget.value)}
            placeholder="username"
            aria-describedby={usernameDescriptionIds}
            aria-invalid={Boolean(validationMessage)}
            autoComplete="off"
