import { copyCommitSearchResult } from "./commitSearchCache";
import type { CommitData } from "./commitTypes";

// The cache only helps once a search has finished. Until then every concurrent request for the
// same username is a separate call to GitHub against one shared token quota -- so a link shared
// with a crowd multiplies into as many upstream searches as there are readers, all asking the
// identical question. Callers that arrive while a search is running now wait for its answer.
//
// Per process, like the cache: a serverless instance coalesces only the requests it serves, and
// the map is empty again on a cold start. It bounds a burst against one instance, not globally.
//
// A joiner inherits the search already in progress, including how much of its 10s timeout budget
// has elapsed -- so joining at 9.5s can surface a timeout almost immediately. That is accepted:
// the key is released either way, so the retry the visitor is offered starts a fresh search with
// a full budget.
const inFlightSearches = new Map<string, Promise<CommitData>>();

/**
 * Runs `startSearch` for `cacheKey`, or joins the run already in progress for it.
 *
 * The key is released as the search settles, including when it fails: a key left behind would
 * make every later search for that username replay the same failure instead of retrying.
 */
export function coalesceCommitSearch(
  cacheKey: string,
  startSearch: () => Promise<CommitData>,
): Promise<CommitData> {
  const inFlight = inFlightSearches.get(cacheKey);
  // Copies rather than the shared object, so one caller cannot mutate what the others receive.
  if (inFlight) return inFlight.then(copyCommitSearchResult);

  // Deferred to a microtask so a synchronous throw from startSearch becomes a rejection of the
  // returned promise rather than escaping the call, which would hand the caller an exception
  // where the signature promises a rejection. The key is not stranded either way -- the throw
  // escapes before `set` runs -- and production passes an arrow that does nothing but call an
  // async function, so it cannot throw synchronously. This keeps the helper honest for any
  // other caller.
  //
  // Invoked inside the arrow rather than passed as `.then(startSearch)`, which would call it
  // unbound and hand it the resolution value as an argument.
  const search = Promise.resolve()
    .then(() => startSearch())
    .finally(() => inFlightSearches.delete(cacheKey));

  inFlightSearches.set(cacheKey, search);

  return search.then(copyCommitSearchResult);
}

export function clearInFlightCommitSearches() {
  inFlightSearches.clear();
}

/** Test seam: proves a settled or failed search leaves nothing behind. */
export function inFlightCommitSearchCount() {
  return inFlightSearches.size;
}

FILE app/_lib/commitSearchRateLimit.ts
// The cache answers a repeated username and the in-flight map shares one search between
// concurrent readers of the same one. Neither touches a flood of *distinct* usernames: every
// one of those is a genuine miss that reaches GitHub, against a search quota of 30 requests
// per minute for the shared token. This bounds what one client can spend of it.
//
// Per client rather than globally, deliberately. A global counter would meet ordinary visitors
// with the rate-limit screen exactly when the app is busiest, and its threshold could only be
// guessed at without traffic data. A per-client window targets the one caller behaving unlike
// a person, so the threshold can sit far above human pace and stop being a guess.
//
// Per process, like the cache and the in-flight map: a serverless instance limits only the
// requests it serves and starts empty on every cold start, so an in-process limit of N is
// really N x instances. This reduces what abuse costs; it is not a quota guarantee, and
// nothing here should be read as a global ceiling. See docs/production.md.
//
// The limiter never learns who a client is. It is handed an opaque key -- a salted hash, from
// app/_lib/searchClientKey.ts -- and never sees the searched username at all, so neither can reach
// a log line or an eviction decision from here.

/**
 * 30 searches per minute, per client. A person types a distinct valid GitHub handle every few
 * seconds at most, so a sustained one every two seconds for a full minute is not a person; a
 * visitor clicking every recent-search shortcut they have does not come close. It is also the
 * documented ceiling for authenticated GitHub search, so a client past it is on its own able
 * to spend the whole shared per-minute allowance.
 */
export const COMMIT_SEARCH_RATE_LIMIT_MAX_SEARCHES = 30;
export const COMMIT_SEARCH_RATE_LIMIT_WINDOW_MS = 60_000;

/**
 * A map keyed by client is a memory-exhaustion vector if it is allowed to grow with the number
 * of distinct keys that arrive, which is the one thing a flood produces cheaply. Idle clients
 * are dropped as the window passes them and this caps what is left, so the map costs a bounded
 * amount however many keys it is shown -- a few hundred kilobytes at most.
 */
export const COMMIT_SEARCH_RATE_LIMIT_MAX_CLIENTS = 500;

/**
 * Search times inside the current window, per client, oldest first. A rolling window rather
 * than a counter that resets on a fixed boundary, which would let a client spend two full
 * allowances back to back across one.
 *
 * Each list is capped by the limit itself: a refused search is not recorded, so a client that
 * keeps trying does not grow its own entry.
 */
const recentSearchTimes = new Map<string, number[]>();

function dropIdleClients(now: number) {
  const windowStart = now - COMMIT_SEARCH_RATE_LIMIT_WINDOW_MS;

  for (const [clientKey, searchTimes] of recentSearchTimes) {
    const lastSearchedAt = searchTimes[searchTimes.length - 1];
    if (lastSearchedAt === undefined || lastSearchedAt <= windowStart) {
      recentSearchTimes.delete(clientKey);
    }
  }
}

function evictLeastRecentlyActiveClients() {
  while (recentSearchTimes.size > COMMIT_SEARCH_RATE_LIMIT_MAX_CLIENTS) {
    const oldestClientKey = recentSearchTimes.keys().next().value;
    if (oldestClientKey === undefined) return;
    recentSearchTimes.delete(oldestClientKey);
  }
}

/**
 * Records a search for `clientKey` and reports whether it is within the window's allowance.
 *
 * Eviction only ever forgets a client, which refills its allowance. That is the direction this
 * has to fail in: a caller who can influence which key it is counted under must not be able to
 * push another client into being refused.
 */
export function allowCommitSearch(clientKey: string, now = Date.now()): boolean {
  const windowStart = now - COMMIT_SEARCH_RATE_LIMIT_WINDOW_MS;
  const searchTimes = (recentSearchTimes.get(clientKey) ?? []).filter(
    (searchedAt) => searchedAt > windowStart,
  );

  const allowed = searchTimes.length < COMMIT_SEARCH_RATE_LIMIT_MAX_SEARCHES;
  if (allowed) searchTimes.push(now);

  // Re-inserted so iteration order stays least-recently-active first, which is what eviction
  // reads. A refused client is re-inserted too: being evicted is a reprieve, so the client
  // being refused right now is the last one that should get it.
  recentSearchTimes.delete(clientKey);
  recentSearchTimes.set(clientKey, searchTimes);

  dropIdleClients(now);
  evictLeastRecentlyActiveClients();

  return allowed;
}

export function clearCommitSearchRateLimit() {
  recentSearchTimes.clear();
}

/** Test seam: proves the map stays bounded under a flood of distinct keys. */
export function trackedCommitSearchClientCount() {
  return recentSearchTimes.size;
}

/**
 * Test seam: proves what is retained is an opaque key and nothing else -- no username, and no
 * raw client identifier.
 */
export function trackedCommitSearchClientKeys() {
  return [...recentSearchTimes.keys()];
}

FILE app/_lib/commitTypes.ts
export type CommitInfo = {
  message: string;
  date: string;
  html_url: string;
  sha: string;
  repository: {
    name: string;
    owner: string;
    full_name: string;
  };
  author: {
    login: string;
    avatar_url: string;
    html_url: string;
  };
};

export type CommitErrorKind =
  "empty" | "rate_limit" | "timeout" | "unavailable" | "validation" | "unknown";

/**
 * A search that found commits. The tuple is the invariant: a successful result with an empty list
 * was representable before, and every consumer paid for it with a defensive check that could never
 * fire -- `result.found && result.commits.length > 0` in the page, a `if (!firstCommit) return null`
 * in the results view. `found` alone is now enough.
 */
export type CommitSearchSuccess = {
  found: true;
  commits: [CommitInfo, ...CommitInfo[]];
  /**
   * GitHub reported `incomplete_results`, meaning the search timed out before scanning every
   * commit. An earlier commit may exist that this result misses, so partial results are surfaced
   * to the visitor and never cached.
   */
  incomplete?: boolean;
};

/**
 * A search that returned nothing usable. `error` and `errorKind` are required rather than optional:
 * every failure the server action produces carries both, and leaving them optional meant each
 * reader deciding for itself what an absent kind meant.
 *
 * `incomplete` lives on both variants deliberately. A search can time out before scanning every
 * commit and return nothing, which is a failure the visitor should be told is unfinished rather
 * than told is an absence of commits.
 */
export type CommitSearchFailure = {
  found: false;
  commits: [];
  error: string;
  errorKind: CommitErrorKind;
  incomplete?: boolean;
};

/**
 * Discriminated on `found`, so narrowing gives a reader the right shape without a cast and makes
 * an impossible combination -- a failure kind on a success, commits on a failure -- fail to
 * compile rather than fail a runtime check somebody remembered to write.
 *
 * The wire format is unchanged. Tuples are erased at runtime, so what the Server Action serializes
 * is the same JSON it always was, and a result cached by an older instance still deserializes.
 */
export type CommitData = CommitSearchSuccess | CommitSearchFailure;

/**
 * The two failure messages the search reaches for when GitHub returns nothing usable. They live
 * beside the constructor that carries them, and are shared rather than copied because the browser
 * fixtures assert on the same wording: a second copy would let the real path and the fixture path
 * describe the same outcome differently, which is the drift `commitSearchMocksEnabled` exists to
 * prevent one level down.
 */
export const EMPTY_COMMIT_SEARCH_MESSAGE =
  "No public commits found for this user (or indexing is delayed).";
export const INCOMPLETE_COMMIT_SEARCH_MESSAGE =
  "GitHub could not finish this search, so no commits were returned yet.";

/**
 * Builds a failure. Paired here with `toCommitSearchSuccess` below so both constructors of the
 * union live with the union, and so callers outside the server action can build one -- a
 * `"use server"` module cannot export a synchronous helper, which is what put this here rather
 * than leaving it in `actions.ts`.
 */
export function commitSearchError(
  error: string,
  errorKind: CommitErrorKind,
  incomplete = false,
): CommitSearchFailure {
  return { found: false, error, errorKind, ...(incomplete ? { incomplete } : {}), commits: [] };
}

/**
 * Builds a success, or returns `null` when there is nothing to succeed with.
 *
 * This exists so the non-empty invariant is established in exactly one place. TypeScript does not
 * narrow `CommitInfo[]` to a non-empty tuple from a `length === 0` check, so without it every
 * construction site would need its own assertion -- and an assertion is a promise the compiler
 * cannot keep. Callers turn `null` into whichever empty-result message fits their context.
 */
export function toCommitSearchSuccess(
  commits: CommitInfo[],
  options: { incomplete?: boolean } = {},
): CommitSearchSuccess | null {
  const [first, ...rest] = commits;

  if (!first) return null;

  return {
    found: true,
    commits: [first, ...rest],
    ...(options.incomplete ? { incomplete: true } : {}),
  };
}

FILE app/_lib/e2eCommitSearchFixtures.ts
/**
 * Deterministic fixtures for the browser suite, and nothing else.
 *
 * Lifted out of `app/_lib/actions.ts`, where they were 173 of 569 lines: thirty percent of the
 * `"use server"` module that queries GitHub with the token was test doubles, including one fixture
 * that throws on purpose and two that mutate process state between calls. Separating them leaves
 * that file as the production search path, lets coverage measure it honestly, and stops the
 * scaffolding shipping inside the module that matters most.
 *
 * Reached only when `E2E_COMMIT_SEARCH_MOCKS=1`, which `commitSearchMocksEnabled` decides for both
 * this module and `app/api/e2e-readiness/route.ts` -- the preflight that tells Playwright whether a
 * server it did not start will serve fixtures at all.
 *
 * No unit tests, deliberately. Every case here exists to be exercised through a browser, and the
 * Playwright suite is the regression test: a fixture that stops resolving fails the journey that
 * depends on it. That is also why this module is excluded from coverage, on the same footing as the
 * other files the gate covers by running rather than importing.
 *
 * The reserved usernames are documented in the E2E mocks gotcha in AGENTS.md. Add a case here and
 * add it there.
 */

import {
  EMPTY_COMMIT_SEARCH_MESSAGE,
  INCOMPLETE_COMMIT_SEARCH_MESSAGE,
  commitSearchError,
} from "./commitTypes";
import type { CommitData, CommitInfo } from "./commitTypes";
import { commitSearchMocksEnabled } from "./e2eCommitSearchMocks";
import { githubProfileUrl } from "./githubUrls";

const E2E_COMMIT_SEARCH_MOCKS_ENABLED = commitSearchMocksEnabled();

/** How long `e2e-slow-result` stalls, so a test can observe the pending state before it settles. */
export const E2E_SLOW_SEARCH_DELAY_MS = 750;

const E2E_REJECT_ONCE_USERNAME_PREFIX = "e2e-reject-once-";
const E2E_INCOMPLETE_ONCE_USERNAME_PREFIX = "e2e-incomplete-once-";
const E2E_INCOMPLETE_THEN_ERROR_USERNAME_PREFIX = "e2e-incomplete-then-error-";

// Per process, which is the point: a test can prove a retry re-issued the search rather than
// re-rendered the previous answer. Each such test uses a unique username, keyed on the Playwright
// worker index, so two tests cannot consume each other's first attempt.
const e2eRejectedUsernames = new Set<string>();
const e2eServedPartialUsernames = new Set<string>();

/**
 * Whether this search should fail as an unhandled Server Action rejection.
 *
 * Separate from the fixture results below because it cannot return one: the point is to throw, so
 * the client exercises the path where a Server Action rejects rather than resolves. Marks the
 * username as spent, so the retry that follows succeeds.
 */
export function shouldRejectCommitSearchOnce(username: string) {
  if (!E2E_COMMIT_SEARCH_MOCKS_ENABLED) return false;
  if (!username.startsWith(E2E_REJECT_ONCE_USERNAME_PREFIX)) return false;
  if (e2eRejectedUsernames.has(username)) return false;

  e2eRejectedUsernames.add(username);

  return true;
}

export function getE2eCommitSearchResult(username: string): CommitData | null {
  if (!E2E_COMMIT_SEARCH_MOCKS_ENABLED) return null;

  // Keep browser tests deterministic without coupling them to GitHub search availability.
  const mockCommit: CommitInfo = {
    message: "Initial public commit\n\nAdd the first project files",
    date: "2020-01-02T03:04:05Z",
    html_url: "https://github.com/e2e-user/origin-repo/commit/abcdef123456",
    sha: "abcdef123456",
    repository: {
      name: "origin-repo",
      owner: "e2e-user",
      full_name: "e2e-user/origin-repo",
    },
    author: {
      login: username,
      avatar_url: "https://github.com/ghost.png",
      html_url: githubProfileUrl(username),
    },
  };

  const completeResult = (): CommitData => ({
    found: true,
    commits: [
      mockCommit,
      {
        ...mockCommit,
        message: "Follow-up commit",
        html_url: "https://github.com/e2e-user/next-repo/commit/bcdefa234567",
        sha: "bcdefa234567",
        repository: {
          name: "next-repo",
          owner: "e2e-user",
          full_name: "e2e-user/next-repo",
        },
      },
    ],
  });

  if (
    username === "e2e-result" ||
    username === "e2e-slow-result" ||
    username.startsWith(E2E_REJECT_ONCE_USERNAME_PREFIX)
  ) {
    return completeResult();
  }

  // Every field at a length or shape that has nowhere to wrap: a repository name with no spaces,
  // a subject that is one unbroken token, a body carrying a long URL, and a 39-character owner.
  // The other fixtures are all short, so they render identically whether or not the card handles
  // long content -- which is why the overflow this reproduces went unnoticed.
  if (username === "e2e-long-data") {
    const owner = "a".repeat(39);
    const repositoryName = "supercalifragilisticexpialidocious-monorepo-services-platform";

    return {
      found: true,
      commits: [
        {
          ...mockCommit,
          message: [
            "Refactorthecommitindexingpipelineandnormalizeeverydownstreamconsumer",
            "",
            "See https://github.com/" +
              owner +
              "/" +
              repositoryName +
              "/pull/12345#issuecomment-9876543210",
          ].join("\n"),
          repository: {
            name: repositoryName,
            owner,
            full_name: owner + "/" + repositoryName,
          },
          author: { ...mockCommit.author, login: owner },
        },
        {
          ...mockCommit,
          message: "Follow-up with an unbroken subject line that keeps going and going and going",
          html_url: "https://github.com/e2e-user/next-repo/commit/bcdefa234567",
          sha: "bcdefa234567",
          repository: {
            name: repositoryName,
            owner,
            full_name: owner + "/" + repositoryName,
          },
          author: { ...mockCommit.author, login: owner },
        },
      ],
    };
  }

  if (username === "e2e-incomplete") {
    return {
      found: true,
      incomplete: true,
      commits: [mockCommit],
    };
  }

  // Stateful, so a browser test can prove a retry re-issues the search rather than
  // re-rendering the same state: partial first, then the outcome the prefix names.
  if (
    username.startsWith(E2E_INCOMPLETE_ONCE_USERNAME_PREFIX) ||
    username.startsWith(E2E_INCOMPLETE_THEN_ERROR_USERNAME_PREFIX)
  ) {
    if (!e2eServedPartialUsernames.has(username)) {
      e2eServedPartialUsernames.add(username);
      return {
        found: true,
        incomplete: true,
        commits: [mockCommit],
      };
    }

    if (username.startsWith(E2E_INCOMPLETE_THEN_ERROR_USERNAME_PREFIX)) {
      return commitSearchError(
        "GitHub rate limit reached. Please try again in a few minutes.",
        "rate_limit",
      );
    }

    return completeResult();
  }

  if (username === "e2e-malformed-dates") {
    return {
      found: true,
      commits: [
        mockCommit,
        {
          ...mockCommit,
          message: "Commit with malformed date",
          date: "not-a-date",
          html_url: "https://github.com/e2e-user/next-repo/commit/bcdefa234567",
          sha: "bcdefa234567",
          repository: {
            name: "next-repo",
            owner: "e2e-user",
            full_name: "e2e-user/next-repo",
          },
        },
      ],
    };
  }

  switch (username) {
    case "e2e-empty":
      return commitSearchError(EMPTY_COMMIT_SEARCH_MESSAGE, "empty");
    case "e2e-incomplete-empty":
      return commitSearchError(INCOMPLETE_COMMIT_SEARCH_MESSAGE, "empty", true);
    case "e2e-rate-limit":
      return commitSearchError(
        "GitHub rate limit reached. Please try again in a few minutes.",
        "rate_limit",
      );
    case "e2e-unavailable":
      return commitSearchError(
        "GitHub is temporarily unavailable. Please try again soon.",
        "unavailable",
      );
    case "e2e-timeout":
      return commitSearchError("GitHub took too long to respond. Please try again.", "timeout");
    case "e2e-unknown":
      return commitSearchError("GitHub commit search failed. Please try again.", "unknown");
    // GitHub rejecting the search itself, which the client's own username validation cannot
    // produce -- the handle is well-formed, and the refusal comes back from the search.
    case "e2e-validation":
      return commitSearchError("GitHub rejected that search.", "validation");
    default:
      return null;
  }
}

FILE app/_lib/e2eCommitSearchMocks.ts
/**
 * Whether the commit search serves browser fixtures instead of querying GitHub.
 *
 * One definition, read by two callers: `app/_lib/actions.ts`, which decides what a search returns,
 * and `app/api/e2e-readiness/route.ts`, which tells the Playwright preflight what this server will
 * do. A second copy of the comparison could drift -- accepting `"true"` in one place and only `"1"`
 * in the other -- and the failure mode is a server that reports itself ready and then sends every
 * reserved `e2e-*` username to real GitHub, which is exactly what the preflight exists to catch.
 *
 * `app/_lib/actions.ts` is a `"use server"` module, so it cannot export a synchronous predicate
 * itself.
 */
/**
 * An index signature rather than the one named key, so `process.env` satisfies it and a test can
 * still pass a bare object literal. A type listing only optional named properties is a weak type
 * that `NodeJS.ProcessEnv` does not satisfy.
 */
export type EnvLike = Record<string, string | undefined>;

export function commitSearchMocksEnabled(env: EnvLike = process.env) {
  return env.E2E_COMMIT_SEARCH_MOCKS === "1";
}

