import Image from "next/image";
import { formatDistanceToNow } from "date-fns";
import { GoGitCommit, GoRepo } from "react-icons/go";
import type { CommitInfo } from "../_lib/commitTypes";
import { githubProfileUrl, githubRepositoryUrl } from "../_lib/githubUrls";

type FirstCommitDisplayProps = {
  data: CommitInfo;
  isMain?: boolean;
};

// Built once at module scope rather than on every call. `Intl.DateTimeFormat` is among the more
// expensive constructors the platform offers -- it resolves a locale and builds a pattern each time
// -- and a rendered result was constructing eleven of them: the hover title on each of the ten
// commit cards, plus the summary date on the main one, repeated on every re-render a retry or a
// share status caused. Both configurations are constant, and both are deliberately pinned to `en`
// and UTC so a commit reads the same date wherever it is viewed, so there is nothing per-call to
// close over and nothing a shared instance can leak between cards.
const commitDateFormat = new Intl.DateTimeFormat("en", {
  month: "short",
  day: "numeric",
  year: "numeric",
  timeZone: "UTC",
});

const commitDateTimeFormat = new Intl.DateTimeFormat("en", {
  dateStyle: "medium",
  timeStyle: "short",
  timeZone: "UTC",
});

export default function FirstCommitDisplay({ data, isMain = true }: FirstCommitDisplayProps) {
  const parsedDate = new Date(data.date);
  const dateObj = Number.isNaN(parsedDate.getTime()) ? null : parsedDate;
  const widthClass = isMain ? "max-w-2xl" : "max-w-xl";
  const shortSha = data.sha.substring(0, 7);
  const [commitSubject, ...commitBodyLines] = data.message.split("\n");
  const commitBody = commitBodyLines.join("\n").trim();

  return (
    <div
      data-commit-card
      className={`w-full ${widthClass} mx-auto border border-[var(--github-border)] rounded-md overflow-hidden font-sans text-sm shadow-sm bg-white`}
    >
      {/* Repository Header */}
      <div className="flex items-start justify-between gap-2 px-4 py-3 border-b border-[var(--github-border)] bg-[var(--github-gray-light)] text-[var(--github-gray-text)]">
        {/* `min-w-0` is what lets this shrink at all: a flex item's automatic minimum size is its
            content, so without it a long owner or repository name pushes the header wider than
            the card and the card clips it. `wrap-anywhere` then lets the name break, which a
            repository name with no spaces otherwise cannot do. */}
        <div className="flex min-w-0 items-start gap-1.5">
          <GoRepo aria-hidden="true" className="mt-0.5 shrink-0 text-base" />
          {/* One text flow rather than three flex items: as flex items the separator wraps onto a
              line of its own once a name is long, which reads as a stray slash. */}
          <div className="min-w-0 wrap-anywhere">
            <a
              href={githubProfileUrl(data.repository.owner)}
              className="hover:text-[var(--github-blue)] hover:underline"
            >
              {data.repository.owner}
            </a>{" "}
            <span>/</span>{" "}
            <a
              href={githubRepositoryUrl(data.repository.full_name)}
              className="font-semibold hover:text-[var(--github-blue)] hover:underline text-[var(--github-gray-dark)]"
            >
              {data.repository.name}
            </a>
          </div>
        </div>
        <div className="shrink-0 font-mono text-xs">
          <span className="opacity-60">commit </span>
          <a href={data.html_url} className="hover:text-[var(--github-blue)] hover:underline">
            {shortSha}
          </a>
        </div>
      </div>

      {/* Main Content */}
      <div className="p-4 sm:p-6 bg-white">
        <div className="flex items-start gap-4">
          <div className="flex-shrink-0 pt-1">
            {/* Avatar */}
            <Image
              src={data.author.avatar_url}
              alt=""
              width={40}
              height={40}
              className="w-10 h-10 rounded-full border border-[var(--github-border)]"
            />
          </div>
          <div className="flex-1 min-w-0">
            <div className="mb-1">
              <a
                href={data.html_url}
                className="text-lg font-semibold text-[var(--github-gray-dark)] hover:text-[var(--github-blue)] hover:underline break-words"
              >
                {commitSubject}
              </a>
            </div>

            {commitBody ? (
              <div className="mt-2 mb-3 text-[var(--github-gray-dark)] font-mono text-xs whitespace-pre-wrap wrap-anywhere bg-[var(--github-gray-light)] p-2 rounded border border-[var(--github-border)]">
                {commitBody}
              </div>
            ) : null}

            <div className="flex flex-wrap items-center gap-1 text-[var(--github-gray-text)] text-xs mt-1">
              <a
                href={data.author.html_url}
                className="wrap-anywhere font-semibold text-[var(--github-gray-dark)] hover:text-[var(--github-blue)] hover:underline"
              >
                {data.author.login}
              </a>
              <span>committed</span>
              {dateObj ? (
                <time dateTime={data.date} title={commitDateTimeFormat.format(dateObj)}>
                  {formatDistanceToNow(dateObj, { addSuffix: true })}
                </time>
              ) : (
                <span>Date unavailable</span>
              )}
            </div>
            {/* Every cell below needs `min-w-0`: a grid item's automatic minimum size is its
                content, so the `truncate` on the repository name -- which is `white-space: nowrap`
                -- widened its track to the full name and pushed the card past the viewport
                instead of ellipsing inside it. */}
            {isMain && (
              <dl className="mt-4 grid gap-2 text-xs text-[var(--github-gray-text)] sm:grid-cols-3">
                <div className="min-w-0 rounded-md border border-[var(--github-border)] bg-[var(--github-gray-light)] px-3 py-2">
                  <dt className="font-semibold text-[var(--github-gray-dark)]">Commit date</dt>
                  <dd className="mt-1">
                    {dateObj ? (
                      <time dateTime={data.date}>{commitDateFormat.format(dateObj)}</time>
                    ) : (
                      "Date unavailable"
                    )}
                  </dd>
                </div>
                <div className="min-w-0 rounded-md border border-[var(--github-border)] bg-[var(--github-gray-light)] px-3 py-2">
                  <dt className="font-semibold text-[var(--github-gray-dark)]">Commit age</dt>
                  <dd className="mt-1">
                    {dateObj ? formatDistanceToNow(dateObj, { addSuffix: false }) : "Unavailable"}
                  </dd>
                </div>
                <div className="min-w-0 rounded-md border border-[var(--github-border)] bg-[var(--github-gray-light)] px-3 py-2">
                  <dt className="font-semibold text-[var(--github-gray-dark)]">
                    Source repository
                  </dt>
                  {/* Wrapped rather than truncated with a `title`: a tooltip is unreachable by
                      touch, so at the width where the name stops fitting it also stops being
                      readable -- which is the width this needs to work at. */}
                  <dd className="mt-1 wrap-anywhere">{data.repository.full_name}</dd>
                </div>
              </dl>
            )}
          </div>
        </div>
      </div>

      {/* Footer Link */}
      <div className="bg-[var(--github-gray-light)] border-t border-[var(--github-border)] px-4 py-2 text-center">
        <a
          href={data.html_url}
          target="_blank"
          rel="noopener noreferrer"
          className="text-xs font-semibold text-[var(--github-blue)] hover:underline flex items-center justify-center gap-1"
        >
          View full commit on GitHub <GoGitCommit aria-hidden="true" />
        </a>
      </div>
    </div>
  );
}
type SearchShortcutSectionProps = {
  title: string;
  usernames: string[];
  isPending: boolean;
  onSearch: (username: string) => void;
  getButtonLabel: (username: string) => string;
  buttonAriaLabel: (username: string) => string;
  onClear?: () => void;
};

export default function SearchShortcutSection({
  title,
  usernames,
  isPending,
  onSearch,
  getButtonLabel,
  buttonAriaLabel,
  onClear,
}: SearchShortcutSectionProps) {
  if (usernames.length === 0) return null;

  return (
    <section
      aria-labelledby={`${title.toLowerCase().replace(/\s+/g, "-")}-heading`}
      aria-busy={isPending}
      className="mt-4 w-full max-w-md"
    >
      <div className="flex items-center justify-between gap-3">
        <h2
          id={`${title.toLowerCase().replace(/\s+/g, "-")}-heading`}
          className="text-xs font-semibold uppercase tracking-normal text-[var(--github-gray-text)]"
        >
          {title}
        </h2>
        {onClear ? (
          <button
            type="button"
            onClick={onClear}
            disabled={isPending}
            aria-label="Clear recent searches"
            className="rounded-sm text-xs font-medium text-[var(--github-gray-text)] hover:text-[var(--github-blue)] focus:outline-none focus:ring-2 focus:ring-[var(--github-blue)] focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
          >
            Clear
          </button>
        ) : null}
      </div>
      <div className="mt-2 flex flex-wrap gap-2">
        {usernames.map((username) => (
          <button
            key={username}
            type="button"
            disabled={isPending}
            onClick={() => onSearch(username)}
            // A GitHub handle is an unbreakable 39-character token, so at a 320px viewport --
            // the width 200% zoom produces on a 640px window -- one shortcut is wider than the
            // page and scrolls it sideways. Wrapping inside the button keeps it a single tap
            // target with one focus ring, which truncating would also do but at the cost of
            // hiding the end of the handle.
            //
            // `break-all`, not `break-words`: the label is an anonymous flex item, whose
            // automatic minimum size is its min-content width. `overflow-wrap: break-word`
            // wraps text but leaves that width at the whole token, so the item refuses to
            // shrink and the label overruns its own padding instead. `word-break: break-all`
            // lowers it to one character, which is what lets `max-w-full` take effect.
            className="inline-flex max-w-full items-center justify-center rounded-md border border-[var(--github-border)] bg-white px-3 py-1.5 text-sm font-medium break-all text-[var(--github-gray-dark)] hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-[var(--github-blue)] focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50"
            aria-label={buttonAriaLabel(username)}
