  // would each call GitHub against one shared quota.
  return coalesceCommitSearch(cacheKey, () => searchGitHubCommits(normalizedUsername, cacheKey));
}

async function searchGitHubCommits(
  normalizedUsername: string,
  cacheKey: string,
